"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["74260"],{89924(e,t,n){n.d(t,{Ay:()=>a,RM:()=>i});var o=n(74848),s=n(28453);let i=[];function r(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"got-a-little-angry-this-morning",children:"Got a Little Angry This Morning"})}),"\n",(0,o.jsxs)(t.blockquote,{children:["\n",(0,o.jsx)(t.p,{children:"2008/6/19 8:11:01"}),"\n"]}),"\n",(0,o.jsxs)("div",{style:{color:"#990000",fontWeight:"500",fontSize:"18px"},children:[(0,o.jsx)(t.p,{children:"Last night I already reported that I was safe. Now I'm honoring my promise to come up and talk about the details and stocks."}),(0,o.jsx)(t.p,{children:"Coming to this hospital, since it was arranged through direct Beijing connections to the hospital's senior management, the people in the department here are all extremely respectful to this ID. And this ID's personality is such that the more deferential people are, the more humble I become. So with the people here, joking around is the most common thing\u2014it's been quite enjoyable, to the point I don't even want to transfer departments. But this morning I got a little angry."}),(0,o.jsx)(t.p,{children:"The IV drip went until 4 AM, still dripping the last 1,000 CC of nutrient solution\u2014some kind of sodium lactate or something, this ID didn't look carefully. Yet two hours had passed and barely anything had dripped. At this rate, it wouldn't be done by 10 AM today. The previous medication change was already late, and blood nearly sprayed out of the IV tube. Specifically, it was probably a shift change\u2014the previous nurse was one of the best here, everything so reassuring. She finished administering the chemo drugs and left, replaced by what was probably a newcomer who was all thumbs. After 20 consecutive hours of hydration therapy plus chemotherapy, and seeing that at least 6 more hours of this remained\u2014and most heartbreaking of all, today being the last day of hydration therapy requiring at least another 10 consecutive hours\u2014the anger started building. I demanded they stop this drip, saying this ID is perfectly healthy. After finishing chemo, I'd even eaten a big late-night snack. There's nowhere that needs this much IV nutrition. Doctors should adjust treatment based on the patient's specific condition, not apply one template to everyone. That nurse, probably unhappy about working the night shift, started arguing back with this ID. This ID then got angry and said: please remove the drip immediately. The patient has this right. Specifics can be explained to the doctor tomorrow. You can also report to the doctor."}),(0,o.jsx)(t.p,{children:"Result: the drip was removed, but the needle was left in, and there's still blood swishing around in the remaining short tube segment. But just now when she came to deliver oral medication, this ID already told her: the medication wasn't prescribed by her, it's not her business. She was just carrying out orders. This ID fully understands. That's really the case\u2014in such a hierarchical hospital system, many things truly aren't their responsibility. On this point, this ID was confused in the wee hours."})]}),"\n",(0,o.jsxs)("div",{style:{color:"#666600",fontWeight:"500",fontSize:"18px"},children:[(0,o.jsx)(t.p,{children:"As for stocks, there's absolutely no place for confusion. Approaching 2,700 points, combined with the interval nesting at smaller levels, everything unfolded as expected\u2014the second hub's rebound has begun. As long as 2,917 holds and the stroke extension conditions continue to be met, those who bottom-fished can continue holding. Otherwise, positions should be reduced in batches."}),(0,o.jsx)(t.p,{children:"Note: the rhythm here isn't to enter only after the previous high or 2,917 is confirmed\u2014rather, you enter as soon as the interval nesting is established. It's actually whether it holds the previous levels that determines whether to exit. Why is this? The lessons explain it very clearly. Getting confused is self-inflicted."})]})]})}function a(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(r,{...e})}):r(e)}},90534(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>u,frontMatter:()=>a,contentTitle:()=>h,toc:()=>d,assets:()=>l});var o=JSON.parse('{"id":"stocks/gotangry","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/stocks/gotangry.md","sourceDirName":"stocks","slug":"/stocks/gotangry","permalink":"/en/stocks/gotangry","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"gotangry","title":"","hide_table_of_contents":true,"sidebar_label":"Got a Little Annoyed This Morning (2008/6/19 8:11:01)"},"sidebar":"stocksExtendedSidebar","previous":{"title":"Today Is the Most Dangerous (2008/6/18 8:04:09)","permalink":"/en/stocks/mostdangeroustoday"},"next":{"title":"Finally Have Time to Come Up and Say a Few Words (2008/6/20 21:37:15)","permalink":"/en/stocks/finallyfreeforfewwords"}}'),s=n(74848),i=n(28453),r=n(89924);let a={id:"gotangry",title:"",hide_table_of_contents:!0,sidebar_label:"Got a Little Annoyed This Morning (2008/6/19 8:11:01)"},h,l={},d=[...r.RM];function c(e){return(0,s.jsx)(r.Ay,{})}function u(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},28453(e,t,n){n.d(t,{R:()=>r,x:()=>a});var o=n(96540);let s={},i=o.createContext(s);function r(e){let t=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);